    def edge_runs(side):
        # side is top/bottom (coordinate is column) or left/right (row)
        n = w if side in ('top', 'bottom') else h
        def val(i):
            return grid[0][i] if side == 'top' else grid[h-1][i] if side == 'bottom' else grid[i][0] if side == 'left' else grid[i][w-1]
        found=[]; i=0
        while i<n:
            if val(i)==bg:
                i+=1; continue
            color=val(i); a=i
            while i<n and val(i)==color: i+=1
            found.append((a,i,color))
        return found

    pairs=[]
    for a,b,color in edge_runs('top'):
        for x,y,col in edge_runs('bottom'):
            if col==color and y-x==b-a:
                pairs.append(('tb',a,b,x,y))
    for a,b,color in edge_runs('left'):
        for x,y,col in edge_runs('right'):
            if col==color and y-x==b-a:
                pairs.append(('lr',a,b,x,y))

    marks=[(r,c,grid[r][c]) for r in range(1,h-1) for c in range(1,w-1) if grid[r][c]!=bg]
    for r,c,color in marks:
        for axis,a,b,x,y in pairs:
            source_side=None; coord=None; mapped=None
            if axis=='tb' and a<=c<b:
                source_side='top'; coord=c; mapped=x+(c-a)
            elif axis=='tb' and x<=c<y:
                source_side='bottom'; coord=c; mapped=a+(c-x)
            elif axis=='lr' and a<=r<b:
                source_side='left'; coord=r; mapped=x+(r-a)
            elif axis=='lr' and x<=r<y:
                source_side='right'; coord=r; mapped=a+(r-x)
            if source_side is None: continue
            # Paint from the marker to its edge and replace the marker with 4.
            if axis=='tb':
                dr=-1 if source_side=='top' else 1
